function RiskAnalysisPage() {
  const [data, setData] = useState(null)
  const load = useCallback(() => getAnalytics().then(setData).catch(() => {}), [])
  useEffect(() => { load(); const timer = setInterval(load, 5000); return () => clearInterval(timer) }, [load])
  const trend = (data?.trend || []).map(point => ({ ...point, time: formatTime(point.timestamp) }))
  const distribution = ['LOW', 'MODERATE', 'HIGH'].map(key => ({ key, name: riskName[key], value: data?.risk_distribution?.[key] || 0 })).filter(x => x.value > 0)
  const metrics = data?.model_metrics
  return <>
    <PageHeading eyebrow="HISTORICAL ANALYTICS" title="Risk analysis" subtitle="Live prediction distribution, sensor trends, and held-out model evaluation." action={<span className="live-indicator page-live"><span className="pulse-dot"/> API data · auto-refresh</span>}/>
    <div className="stat-grid analytics-stats"><StatCard icon={Activity} label="Total predictions" value={data?.total_predictions} note="Persisted model outputs" tone="blue"/><StatCard icon={Thermometer} label="Avg. body temperature" value={data ? `${data.averages.body_temperature.toFixed(1)}°C` : '—'} note="Across recorded readings" tone="rose"/><StatCard icon={Activity} label="Avg. heart rate" value={data ? `${Math.round(data.averages.heart_rate)} bpm` : '—'} note="Across recorded readings" tone="blue"/><StatCard icon={Wind} label="Avg. ambient temperature" value={data ? `${data.averages.ambient_temperature.toFixed(1)}°C` : '—'} note={`Humidity average ${data?.averages?.humidity ?? '—'}%`} tone="amber"/></div>
    <div className="content-grid analytics-grid"><section className="panel chart-panel"><div className="panel-head compact"><div><h2>Risk distribution</h2><p>Prediction counts stored in the database</p></div></div>{distribution.length?<div className="risk-chart-layout"><div className="risk-pie"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={distribution} dataKey="value" nameKey="name" innerRadius={58} outerRadius={84} paddingAngle={3} stroke="none">{distribution.map(item=><Cell key={item.key} fill={riskColors[item.key]}/>)}</Pie><Tooltip formatter={(v,n)=>[v,`${n} predictions`]}/><Legend verticalAlign="bottom" height={25} iconType="circle" wrapperStyle={{fontSize:10,color:'#78869a'}}/></PieChart></ResponsiveContainer></div><div className="risk-counts">{distribution.map(item=><div key={item.key}><span className={`risk-key ${item.key.toLowerCase()}`}/><span>{item.name} risk</span><strong>{item.value.toLocaleString()}</strong></div>)}</div></div>:<EmptyState title="No predictions yet" text="Risk distribution will appear after readings are processed."/>}</section>
      <section className="panel chart-panel"><div className="panel-head compact"><div><h2>Sensor trends</h2><p>Latest stored body temperature and heart rate readings</p></div></div>{trend.length>1?<div className="chart-wrap analytics-trend"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend} margin={{top:12,right:10,left:-15,bottom:0}}><defs><linearGradient id="tempFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#d97e5f" stopOpacity={.17}/><stop offset="100%" stopColor="#d97e5f" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#edf0f5" vertical={false}/><XAxis dataKey="time" tickLine={false} axisLine={false} tick={{fontSize:9,fill:'#8792a3'}} minTickGap={35}/><YAxis yAxisId="temp" tickLine={false} axisLine={false} tick={{fontSize:9,fill:'#8792a3'}} width={39}/><YAxis yAxisId="heart" orientation="right" tickLine={false} axisLine={false} tick={{fontSize:9,fill:'#8792a3'}} width={35}/><Tooltip labelFormatter={(_,payload)=>payload?.[0]?.payload?.timestamp?formatDate(payload[0].payload.timestamp):''}/><Legend wrapperStyle={{fontSize:9}}/><Area yAxisId="temp" type="monotone" dataKey="body_temperature" name="Body temp °C" stroke="#d97e5f" strokeWidth={2} fill="url(#tempFill)" dot={false}/><Area yAxisId="heart" type="monotone" dataKey="heart_rate" name="Heart rate bpm" stroke="#6684b7" strokeWidth={2} fill="none" dot={false}/></AreaChart></ResponsiveContainer></div>:<EmptyState title="Waiting for sensor history" text="The chart appears after more than one reading."/>}</section></div>
    <section className="panel chart-panel model-panel"><div className="panel-head compact"><div><h2>Random Forest evaluation</h2><p>Held-out synthetic test split · distinct from live prediction results</p></div><span className="model-tag"><BadgeCheck size={14}/> {metrics?.model_version ?? 'Random Forest'}</span></div>{metrics?<><div className="metric-score-grid">{[['Accuracy',metrics.accuracy],['Macro precision',metrics.precision_macro],['Macro recall',metrics.recall_macro],['Macro F1',metrics.f1_macro]].map(([label,value])=><div className="metric-score" key={label}><span>{label}</span><strong>{(value*100).toFixed(1)}<small>%</small></strong></div>)}</div><div className="confusion-wrap"><div><strong>Confusion matrix</strong><span>Rows: actual class · columns: predicted class</span></div><table className="confusion-table"><thead><tr><th>Actual \ Pred.</th>{metrics.labels.map(label=><th key={label}>{riskName[label]}</th>)}</tr></thead><tbody>{metrics.confusion_matrix.map((row,i)=><tr key={metrics.labels[i]}><th>{riskName[metrics.labels[i]]}</th>{row.map((v,j)=><td className={i===j?'matrix-diagonal':''} key={j}>{v}</td>)}</tr>)}</tbody></table></div><p className="model-note">{metrics.evaluation_source}. The model has not been clinically validated.</p></>:<EmptyState title="Model evaluation is unavailable" text="Start the API to load its saved evaluation metrics."/>}</section>
    <div className="risk-footnote">Charts and live records are project demonstration analytics. Risk classifications are not medical diagnoses.</div>
  </>
}

function BlockchainPage() {
  const [data,setData]=useState({items:[],total:0}); const [verification,setVerification]=useState(null); const [busy,setBusy]=useState(false); const [error,setError]=useState('')
  const refresh=useCallback(async()=>{try{const [blocks,check]=await Promise.all([getBlocks({limit:100}),verifyBlockchain()]);setData(blocks);setVerification(check);setError('')}catch(e){setError(e.response?.data?.detail||'Blockchain API is unavailable. Start the backend and database.')}},[])
  useEffect(()=>{refresh();const timer=setInterval(refresh,8000);return()=>clearInterval(timer)},[refresh])
  const verifyNow=async()=>{setBusy(true);try{setVerification(await verifyBlockchain());setError('')}catch(e){setError(e.response?.data?.detail||'Verification request failed.')}finally{setBusy(false)}}
  return <><PageHeading eyebrow="RECORD INTEGRITY" title="Blockchain verification" subtitle="A local SHA-256 chain links stored predictions and their source readings." action={<button className="button button-primary" onClick={verifyNow} disabled={busy}><ShieldCheck size={16}/>{busy?'Verifying…':'Verify chain'}</button>}/>{error&&<div className="error-banner"><AlertTriangle size={16}/><span>{error}</span></div>}
    <div className={`verification-banner ${verification?.valid?'verified':''}`}><div className="verification-mark"><ShieldCheck size={20}/></div><div><strong>{verification?verification.valid?'Chain integrity verified':'Integrity issue found':'Verification pending'}</strong><span>{verification?verification.valid?`${verification.blocks_verified.toLocaleString()} blocks checked · each record hash and previous-block link is valid.`:`${verification.reason||'Verification failed'}${verification.broken_at!=null?` at block ${verification.broken_at}`:''}`:'Run verification to check the persisted SHA-256 chain.'}</span></div><span className="verification-state">{verification?.valid?'INTEGRITY OK':verification?'CHECK REQUIRED':'READY'}</span></div>
    <div className="stat-grid blockchain-stats"><StatCard icon={Fingerprint} label="Blocks stored" value={data.total} note="Prediction records in chain" tone="purple"/><StatCard icon={ShieldCheck} label="Verified blocks" value={verification?.blocks_verified ?? '—'} note="Latest verification result" tone="mint"/><div className="panel chain-head-card"><span>Latest chain hash</span><code>{verification?.latest_hash||'No blocks recorded yet'}</code></div></div>
    <section className="panel history-panel block-panel"><div className="panel-head compact"><div><h2>Block explorer</h2><p>Latest {data.items.length} of {data.total} chained prediction records</p></div><span className="hash-algorithm">SHA-256</span></div>{data.items.length?<div className="readings-table-wrap"><table><thead><tr><th>INDEX</th><th>TIMESTAMP</th><th>RECORD</th><th>RISK</th><th>DATA HASH</th><th>PREVIOUS HASH</th><th>BLOCK HASH</th></tr></thead><tbody>{data.items.map(block=><tr key={block.id}><td><span className="block-index">#{block.block_index}</span></td><td>{formatDate(block.timestamp)}</td><td>Prediction {block.prediction_id}</td><td><RiskPill risk={block.risk}/></td><td><code title={block.data_hash}>{block.data_hash.slice(0,14)}…</code></td><td><code title={block.previous_hash}>{block.previous_hash=== '0'.repeat(64)?'GENESIS':`${block.previous_hash.slice(0,14)}…`}</code></td><td><code title={block.current_hash}>{block.current_hash.slice(0,14)}…</code></td></tr>)}</tbody></table></div>:<EmptyState title="No blockchain records yet" text="Processed predictions are automatically added to the local chain."/>}</section>
    <p className="risk-footnote">This local hash chain demonstrates tamper detection. It is not a distributed public blockchain or a substitute for production security controls.</p>
  </>
}

function SensorChart({data,dataKey,color,unit}) { return <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data} margin={{top:12,right:12,left:-16,bottom:0}}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity={.18}/><stop offset="95%" stopColor={color} stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#edf0f5" vertical={false}/><XAxis dataKey="time" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8792a3'}} minTickGap={35}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8792a3'}} width={48}/><Tooltip contentStyle={{border:'1px solid #e9edf3',borderRadius:10,boxShadow:'0 6px 20px #13274612'}} formatter={v=>[`${Number(v).toFixed(1)} ${unit}`, 'Body temperature']}/><Area type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2.5} fill="url(#chartFill)" dot={false} activeDot={{r:4,strokeWidth:0}}/></AreaChart></ResponsiveContainer></div> }

export default App
